css:
body {
  background-color: #090514;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  margin: 0;
}
.cr80-card {
  width: 337.5px;
  height: 531px;
  background: #120a2b;
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(139, 92, 246, 0.3);
}
.aurora-blur {
  position: absolute;
  width: 300px;
  height: 300px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(139,92,246,0.3) 0%, rgba(6,182,212,0.15) 50%, transparent 100%);
  filter: blur(40px);
  z-index: 1;
  pointer-events: none;
}
.top-glow { top: -150px; right: -100px; }
.bottom-glow { bottom: -150px; left: -100px; }

tailwind_config:
{
      darkMode: "class",
      theme: {
        extend: {
          colors: {
            "primary": "#8b5cf6", // Vibrant Violet
            "primary-container": "#2e1065", // Deep Purple
            "secondary": "#06b6d4", // Cyan Accent
            "secondary-container": "#083344", // Deep Cyan
            "background": "#090514", // Very Dark Violet
            "surface": "#120a2b", // Dark Violet Card Base
            "on-surface": "#f3e8ff",
            "on-primary-container": "#c084fc",
            "on-secondary-container": "#22d3ee",
            "outline-variant": "rgba(139, 92, 246, 0.2)"
          },
          fontFamily: {
            "id-name": ["Hanken Grotesk", "sans-serif"],
            "id-role": ["Inter", "sans-serif"]
          }
        }
      }
    }
